package ug.audiocity.studio;
import java.io.*;import java.util.*;
/** Conservative profiles calibrated against the supplied phone takes; per-region level calibration. */
public final class PhoneVocalPresets {
 public static final String[] NAMES={"Phone / Clean · dry","Phone / Afropop Lead","Phone / Dancehall & Rap","Phone / Soft R&B"};
 public static final class Result {public Core.Fx fx;public double activeDb,noiseDb,peakDb;}
 static double clamp(double x,double lo,double hi){return Math.max(lo,Math.min(hi,x));}
 static double db(double amplitude){return 20*Math.log10(Math.max(1e-7,amplitude));}
 public static Core.Fx profile(int index){if(index<0||index>=NAMES.length)throw new IllegalArgumentException("Unknown phone vocal preset");Core.Fx f=new Core.Fx();f.hpf=true;f.peakGuard=true;f.highPassHz=85;f.midHz=600;f.mid=-1.3;f.high=0;f.comp=true;f.threshold=-21;f.ratio=2.2;f.deess=true;f.deessAmount=.65;f.gate=true;f.gateDb=-60;f.gateFloor=.4;switch(index){case 1:f.highPassHz=90;f.midHz=650;f.mid=-1.5;f.high=.6;f.threshold=-22;f.ratio=2.7;f.deessAmount=.72;f.room=true;f.roomMix=.065;f.delay=true;f.delayMix=.045;f.leftBeats=.5;f.rightBeats=.75;f.delayFeedback=.22;break;case 2:f.highPassHz=95;f.midHz=700;f.mid=-1;f.high=.2;f.threshold=-23;f.ratio=3.1;f.deessAmount=.75;f.room=true;f.roomMix=.035;f.delay=true;f.delayMix=.025;f.leftBeats=.5;f.rightBeats=1;f.delayFeedback=.18;break;case 3:f.highPassHz=80;f.midHz=750;f.mid=-1.8;f.high=-.5;f.threshold=-21;f.ratio=2.1;f.deessAmount=.78;f.room=true;f.roomMix=.10;f.delay=true;f.delayMix=.055;f.leftBeats=.75;f.rightBeats=1;f.delayFeedback=.25;break;}return f;}
 public static Result calibrate(Core.Source source,int index,int bpm)throws IOException {
  int frames=Math.min(source.frames(),Core.RATE*30);if(frames<Core.RATE/2)throw new IOException("Choose at least half a second of vocal audio for calibration.");int block=960,count=(frames+block-1)/block;double[] rms=new double[count];double peak=0;for(int b=0;b<count;b++){double energy=0;int start=b*block,end=Math.min(frames,start+block);for(int i=start;i<end;i++){double l=source.sample(i,0),r=source.sample(i,1);energy+=(l*l+r*r)*.5;peak=Math.max(peak,Math.max(Math.abs(l),Math.abs(r)));}rms[b]=Math.sqrt(energy/Math.max(1,end-start));}if(peak<.002)throw new IOException("The vocal is too quiet to calibrate reliably. Use manual controls or a louder take.");double[] sorted=rms.clone();Arrays.sort(sorted);double noise=sorted[(int)((count-1)*.1)],loud=sorted[(int)((count-1)*.9)];boolean hasQuiet=noise<loud*.25;double floor=hasQuiet?Math.max(noise*5,loud*.1):loud*.15;double energy=0;long samples=0;for(int b=0;b<count;b++)if(rms[b]>floor){int n=Math.min(block,frames-b*block);energy+=rms[b]*rms[b]*n;samples+=n;}if(samples<Core.RATE/4)throw new IOException("Not enough vocal audio to calibrate. Select a region containing the performance.");Result result=new Result();result.activeDb=db(Math.sqrt(energy/samples));result.noiseDb=db(noise);result.peakDb=db(peak);Core.Fx f=profile(index);f.gate=hasQuiet;f.inputDb=clamp(-18-result.activeDb,-6,6);f.gateDb=clamp(result.noiseDb+f.inputDb+10,-65,-40);double remaining=result.activeDb+f.inputDb+18;f.threshold=clamp(f.threshold+remaining,-36,-10);
  // Match active vocal energy through this preset, while retaining peak headroom.
  Core.Processor processor=new Core.Processor();processor.configure(f,bpm);float[] data=new float[block*2];double wet=0,dry=0;for(int b=0;b<count;b++){int n=Math.min(block,frames-b*block);for(int i=0;i<n;i++){data[i*2]=source.sample(b*block+i,0);data[i*2+1]=source.sample(b*block+i,1);}processor.apply(data,n);for(int i=0;i<n;i++){if(rms[b]>floor)wet+=(data[i*2]*data[i*2]+data[i*2+1]*data[i*2+1])*.5;}if(rms[b]>floor)dry+=rms[b]*rms[b]*n;}double match=10*Math.log10(Math.max(1e-15,dry)/Math.max(1e-15,wet));f.outputDb=clamp(match,-9,9);result.fx=f;return result;
 }
}
